from pathlib import Path
import json, sqlite3, sys

CID='MANUAL-SCOUT-HENGELTJES-20260924'
root=Path.home()/'prediction_research_prod'/'knowledge'/'codex_runtime'

def overlay():
    xs=[]
    for p in (root/'candidate_states').glob('*.json'):
        try: x=json.loads(p.read_text())
        except Exception: continue
        if x.get('candidate_id')==CID:
            xs.append((p.stat().st_mtime,p,x))
    if not xs: raise SystemExit('NO_CANDIDATE_OVERLAY')
    return max(xs)[1:]

def tasks():
    db=sqlite3.connect(f"file:{root/'runtime.sqlite'}?mode=ro",uri=True)
    try: rows=db.execute('select id,body,status,attempt from tasks order by rowid').fetchall()
    finally: db.close()
    out=[]
    for tid,body,status,attempt in rows:
        try:b=json.loads(body)
        except Exception:continue
        if b.get('candidate_id')==CID:
            out.append((tid,b,status,attempt))
    return out

def snap(label):
    p,x=overlay(); ts=tasks()
    print('CANARY_PHASE='+label)
    print('OVERLAY_FILE='+str(p))
    print('QUEUE_STATUS='+str(x.get('queue_status')))
    print('BUILD_CONTRACT='+str(isinstance(x.get('build_contract'),dict)))
    print('BUILD_HANDOFF='+json.dumps(x.get('build_handoff'),sort_keys=True))
    for tid,b,status,attempt in ts[-12:]:
        print('TASK',tid,status,'attempt='+str(attempt),'class='+str(b.get('task_class')),'planner='+str(bool(b.get('candidate_build_planner'))),'builder='+str(bool(b.get('candidate_builder') or b.get('sol_builder'))))
    return x,ts

mode=sys.argv[1] if len(sys.argv)>1 else 'snapshot'
x,ts=snap(mode)
if mode!='final': raise SystemExit(0)
planners=[(tid,b,status) for tid,b,status,_ in ts if b.get('candidate_build_planner')]
builds=[(tid,b,status) for tid,b,status,_ in ts if b.get('task_class')=='infrastructure_build']
if not planners:
    print('ASSERT_FAIL=NO_BUILD_PLANNER_TASK')
    raise SystemExit(21)
if not any(status=='COMPLETE' for _,_,status in planners):
    print('ASSERT_FAIL=BUILD_PLANNER_NOT_COMPLETE')
    raise SystemExit(22)
if not builds:
    print('ASSERT_FAIL=NO_INFRASTRUCTURE_BUILD_TASK')
    raise SystemExit(23)
if any(status=='COMPLETE' for _,_,status in builds):
    print('BUILD_CHAIN_ASSERT=BUILDER_COMPLETE')
    print('3333333333333333333333333333333333333333')
else:
    print('BUILD_CHAIN_ASSERT=BUILDER_SELECTED')
    print('2222222222222222222222222222222222222222')
